public class Issue13_triangle_category { public static void main(String[] args) { int a=3, b=4, c=4; if(a<=0 || b<=0 || c<=0 || a+b<c || a+c<b || b+c<a) System.out.println("Invalid"); else if(a==b && b==c) System.out.println("Equilateral"); else if(a==b || a==c) System.out.println("Isosceles"); else System.out.println("Scalene"); } }
